  $('graph-enabled').onclick=()=>{attempt(()=>{store.setting('enabled',!store.data.settings.enabled);if(engine&&store.data.settings.enabled)engine.host.context.resume().catch(()=>{store.setting('enabled',false);message('Não foi possível ativar o contexto de áudio.');});});};
  $('graph-search').oninput=renderCatalog;$('graph-catalog').onclick=e=>{const fresh=e.target.closest('[data-new-type]');if(fresh){if(fresh.dataset.newType==='primary-eq')attempt(()=>select(store.duplicate('main-eq').id));else add(fresh.dataset.newType);return;}const b=e.target.closest('[data-add-type]');if(!b)return;const type=b.dataset.addType,def=M.definitions[type];if(type==='primary-eq'||def.bands||def.peq){if(type!=='primary-eq')store.setParam('main-eq','mode',def.peq?'parametric':String(def.bands));select('main-eq');return;}const current=[...selection].map(id=>store.node(id)).find(n=>n?.type===type),existing=current||store.data.nodes.find(n=>n.type===type);if(existing){select(existing.id);message('Instância existente selecionada. Use ＋ para adicionar outra.');}else add(type);};$('graph-processors').onclick=()=>{const hidden=$('graph-browser').hidden;$('graph-browser').hidden=!hidden;$('graph-processors').setAttribute('aria-expanded',String(hidden));};$('graph-zoom-in').onclick=()=>zoom(1.2);$('graph-zoom-out').onclick=()=>zoom(1/1.2);$('graph-fit').onclick=fit;
  $('graph-arrange').onclick=()=>{const levels=new Map(),counts=new Map();for(const id of M.order(store.data)){const incoming=store.data.edges.filter(e=>e.to===id),level=incoming.length?Math.max(...incoming.map(e=>(levels.get(e.from)||0)+1)):0;levels.set(id,level);}const columns=Math.max(1,Math.floor($('graph-viewport').getBoundingClientRect().width/280)),levelCounts=new Map();for(const level of levels.values())levelCounts.set(level,(levelCounts.get(level)||0)+1);const rows=Math.max(...levelCounts.values()),live=M.liveNodes(store.data);if(columns<2){const ordered=[...store.data.nodes].sort((a,b)=>live.has(b.id)-live.has(a.id));store.move(ordered.map(n=>{const level=levels.get(n.id),row=counts.get(level)||0;counts.set(level,row+1);return{id:n.id,x:60+row*260,y:80+level*220};}));fit();return;}store.move(store.data.nodes.map(n=>{const level=levels.get(n.id),row=counts.get(level)||0;counts.set(level,row+1);return{id:n.id,x:60+(level%columns)*300,y:80+Math.floor(level/columns)*(rows*220+80)+row*220};}));fit();};for(const [id,k]of [['graph-snap','snap'],['graph-motion','motion'],['graph-simple','simple']])$(id).onclick=()=>store.setting(k,!store.data.settings[k]);$('graph-glow').oninput=e=>store.setting('glow',+e.target.value);$('graph-palette').onchange=e=>store.setting('palette',e.target.value);$('graph-undo').onclick=()=>store.undo();$('graph-redo').onclick=()=>store.redo();
