  function preset(name){const next=new M.Store(),types={clean:[],warm:['gain','saturation','tone','meter'],vinyl:['gain','vinyl','tube','meter'],studio:['gain','compressor','meter'],spatial:['gain','width','crossfeed','meter']}[name];if(!types)throw Error('Preset desconhecido.');const shared=copy(store.node('main-eq').params.state);shared.enabled=false;next.setPrimary(shared);let from='main-eq';next.disconnect('direct');types.forEach((type,i)=>{const n=next.add(type,640+i*300,180);if(type==='gain')next.setParam(n.id,'gain',-6);if(type==='tone')next.setParam(n.id,'bass',1.5);if(type==='width')next.setParam(n.id,'width',125);next.connect(from,'out',n.id,'in');from=n.id;});next.connect(from,'out','sink','in');next.move([{id:'sink',x:640+types.length*300,y:180}]);return next.snapshot();}
