  function startMeters(){clearInterval(meterTimer);meterTimer=setInterval(()=>{if(!dialog.open||document.hidden)return;appearance();const real=store.data.settings.enabled&&!audioPreparing&&engine?.enabled&&engine?.current&&api.state.playing&&!api.isDemo();for(const el of $('graph-nodes').querySelectorAll('[data-node].graph-node')){const level=real?engine.current.chain.level(el.dataset.node):null,bar=el.querySelector('.graph-node-meter');bar.firstElementChild.style.width=level?Math.max(0,Math.min(100,(level.peak+60)/60*100))+'%':'0%';bar.classList.toggle('clip',!!level&&level.peak>=0);}const id=[...selection][0],level=real?engine.current.chain.level(id):null;if($('graph-level-peak')){$('graph-level-peak').value=level?format(level.peak):'—';$('graph-level-rms').value=level?format(level.rms):'—';}if($('dsp-live-reduction'))$('dsp-live-reduction').value=level?Math.max(0,-level.reduction).toFixed(1)+' dB':'—';const canvas=$('graph-spectrum');if(canvas){const c=canvas.getContext('2d');c.clearRect(0,0,canvas.width,canvas.height);if(level){c.fillStyle=getComputedStyle(document.documentElement).getPropertyValue('--cyan');for(let i=0;i<40;i++){const v=level.bins[Math.floor(i*level.bins.length/40)]/255;c.fillRect(i*6,70-v*70,3,v*70);}}}},100);}
