  renderCatalog();window.VynampGraph={store,open,fit,preset,select,label:id=>labelFor(store.node(id)),resetComparison:()=>{ab=[store.snapshot(),store.snapshot()];abIndex=0;$('graph-slot-a').setAttribute('aria-pressed','true');$('graph-slot-b').setAttribute('aria-pressed','false');},refresh:()=>{renderCatalog();renderNodes();inspector();appearance();},synchronizeAudio:applyAudio,getSelection:()=>[...selection],setMessage:message,bootstrap:{hadPrimary,hadSavedGraph:!!rawSaved,raw:rawSaved},get engine(){return engine;}};
